<?php
namespace SenderSuite;

/** Native stored inbox and operator controls. No reply transport, sync, receive or execution worker. */
final class Inbox {
    private $db;private $records;
    const LABELS=array('active','unread','interested','not_interested','closed','opportunity');
    public function __construct(Database $db,callable $clock=null){$this->db=$db;$this->records=new Records($db,$clock);}
    private function table($n){return Schema::identifier($this->db->schema()->table($n));}
    public static function definitions(){return array('/inbox/conversations'=>array('GET'),'/inbox/campaign-filters'=>array('GET'),'/inbox/conversations/(?P<conversation_id>-?[0-9]+)'=>array('GET'),'/inbox/conversations/(?P<conversation_id>-?[0-9]+)/templates/(?P<template_id>-?[0-9]+)/preview'=>array('GET'),'/inbox/conversations/(?P<conversation_id>-?[0-9]+)/(?P<action>mark-interested|mark-not-interested|mark-close|mark-opportunity|status|mark-unread|stop-sequence|resume-sequence)'=>array('POST'));}
    private function conversation($id){$r=$this->db->one('conversations',array('id'=>$id));if(!$r){throw new AuthFailure(404,'Conversation not found');}return $r;}
    private function change(array $old,array $patch,$force=false){if(!$force&&array_replace($old,$patch)===$old){return $old;}$stamp=$this->records->now();if($stamp<=$old['updated_at']){$stamp=(new \DateTimeImmutable($old['updated_at'],new \DateTimeZone('UTC')))->modify('+1 microsecond')->format('Y-m-d H:i:s.u');}$patch['updated_at']=$stamp;$where=array_intersect_key($old,array_flip(array('id','updated_at','status','unread_count','message_count','last_message_at','sequence_paused','campaign_id','ads_campaign_id','last_campaign_id','last_ads_campaign_id')));$where['sequence_paused']=(int)$where['sequence_paused'];if($this->db->update('conversations',$patch,$where)!==1){throw new AuthFailure(409,'Conversation changed. Reload and retry.');}return array_replace($old,$patch);}
    private static function custom($c){$v=json_decode($c['custom_fields']??'null');return is_object($v)?$v:new \stdClass();}
    private static function name($c){if(!$c){return 'Unknown';}$s=Compat::strip(Compat::strip($c['first_name']??'').' '.Compat::strip($c['last_name']??''));if($s!==''){return $s;}foreach(array('business_name','phone_number','email') as $k){$s=Compat::strip($c[$k]??'');if($s!==''){return $s;}}return 'Unknown';}
    private static function card($c,$detail=false){if(!$c){return null;}$keys=$detail?array('id','phone_number','first_name','last_name','business_name','lead_status','city','state','email','website','notes'):array('phone_number','lead_status','business_name','first_name','last_name','city','state');$out=array_intersect_key($c,array_flip($keys));$out['custom_fields']=self::custom($c);return $out;}
    private function contacts(array $rows,$detail=false){$ids=array_values(array_unique(array_column($rows,'contact_id')));$out=array();if($ids){foreach($this->db->rows('SELECT id,first_name,last_name,business_name,phone_number,email,lead_status,city,state,custom_fields'.($detail?',website,notes':'').' FROM '.$this->table('contacts').' WHERE id IN ('.implode(',',array_fill(0,count($ids),'%d')).')',$ids) as $c){$c=$this->db->decode('contacts',$c);$out[$c['id']]=$c;}}return $out;}
    /** Source examines only the first/last 50 outgoing messages, including failed/cancelled ones. */
    private function heal(array $r){$patch=array();foreach(array('first','last') as $touch){$prefix=$touch==='first'?'':'last_';if($r[$prefix.'campaign_id']||$r[$prefix.'ads_campaign_id']){continue;}$sort=$touch==='first'?'ASC':'DESC';$rows=$this->db->rows('SELECT campaign_id,ads_campaign_id FROM '.$this->table('messages').' WHERE conversation_id=%d AND direction=%s ORDER BY created_at '.$sort.',id '.$sort.' LIMIT 50',array($r['id'],'outgoing'));foreach($rows as $m){if($m['campaign_id']){$patch[$prefix.'campaign_id']=(int)$m['campaign_id'];break;}if($m['ads_campaign_id']){$patch[$prefix.'ads_campaign_id']=(int)$m['ads_campaign_id'];break;}}}return $patch?$this->change($r,$patch):$r;}
    private function labels(array $rows){$out=array();foreach(array('campaign'=>'campaigns','ads'=>'ads_campaigns') as $kind=>$table){$ids=array();foreach($rows as $r){foreach($kind==='campaign'?array('campaign_id','last_campaign_id'):array('ads_campaign_id','last_ads_campaign_id') as $k){if($r[$k]){$ids[$r[$k]]=true;}}}if($ids){$keys=array_keys($ids);foreach($this->db->rows('SELECT id,name,status FROM '.$this->table($table).' WHERE id IN ('.implode(',',array_fill(0,count($keys),'%d')).')',$keys) as $r){$out[$kind.':'.$r['id']]=array('id'=>(int)$r['id'],'kind'=>$kind,'name'=>$r['name'],'status'=>$r['status']);}}}return $out;}
    private static function badge(array $r,array $labels,$last=false){$p=$last?'last_':'';foreach(array('campaign'=>'campaign_id','ads'=>'ads_campaign_id') as $kind=>$key){if($r[$p.$key]){return $labels[$kind.':'.$r[$p.$key]]??null;}}return null;}
    private function channel($q){return Analytics::channel(DataRoutes::text($q,'channel','sms',null,32));}
    public function listing(array $q){$page=isset($q['page'])?DataRoutes::integer($q['page'],'page',1,1000000):1;$per=isset($q['per_page'])?DataRoutes::integer($q['per_page'],'per_page',1,500):500;$channel=$this->channel($q);$where=array('1=1');$args=array();if($channel!=='all'){$where[]="COALESCE(v.channel,'sms')=%s";$args[]=$channel;}$channelWhere=implode(' AND ',$where);$channelArgs=$args;
        $status=DataRoutes::text($q,'status',null,null,100);if($status!==null&&$status!==''&&$status!=='all'){if($status==='unread'){$where[]="(v.status='unread' OR v.unread_count>0)";}else{$where[]='v.status=%s';$args[]=$status;}}
        foreach(array('campaign_id','ads_campaign_id') as $k){if(isset($q[$k])){$id=DataRoutes::integer($q[$k],$k);$where[]='(v.'.$k.'=%d OR v.last_'.$k.'=%d)';$args[]=$id;$args[]=$id;}}
        if(isset($q['replied_only'])&&DataRoutes::boolean($q['replied_only'],'replied_only')){$where[]='EXISTS (SELECT 1 FROM '.$this->table('messages')." m WHERE m.conversation_id=v.id AND m.direction='incoming')";}
        $search=DataRoutes::text($q,'search',null,null,1000);$join='';if($search!==null&&$search!==''){$join=' JOIN '.$this->table('contacts').' c ON c.id=v.contact_id';$parts=array();foreach(array('c.first_name','c.last_name','c.business_name','c.phone_number','v.last_message_preview') as $col){$parts[]='LOWER('.$col.') LIKE LOWER(%s)';$args[]='%'.$search.'%';}$digits='';foreach(Compat::points($search) as $cp){if(Compat::decimal($cp)!==null){$digits.=Compat::chr($cp);}}if($digits!==''){$variants=array($digits);if(strpos($digits,'0')===0&&strlen($digits)>1){$n=substr($digits,1);$variants[]=$n;$variants[]='234'.$n;}elseif(strpos($digits,'234')===0&&strlen($digits)>3){$n=substr($digits,3);$variants[]=$n;$variants[]='0'.$n;}else{$variants[]='234'.$digits;$variants[]='0'.$digits;}foreach(array_unique($variants) as $s){$parts[]='c.phone_number LIKE %s';$args[]='%'.$s.'%';}}$where[]='('.implode(' OR ',$parts).')';}
        $from=' FROM '.$this->table('conversations').' v'.$join.' WHERE '.implode(' AND ',$where);$total=(int)$this->db->rows('SELECT COUNT(*) AS n'.$from,$args)[0]['n'];$rows=$this->db->rows('SELECT v.*'.$from.' ORDER BY (v.last_message_at IS NULL) ASC,v.last_message_at DESC,v.id ASC LIMIT %d OFFSET %d',array_merge($args,array($per,($page-1)*$per)));$convs=array();foreach($rows as $r){$convs[]=$this->heal($this->db->decode('conversations',$r));}$contacts=$this->contacts($convs);$labels=$this->labels($convs);$items=array();$bytes=0;foreach($convs as $r){$c=$contacts[$r['contact_id']]??null;$item=array('id'=>$r['id'],'channel'=>$r['channel']?:'sms','contact_id'=>$r['contact_id'],'contact_name'=>self::name($c),'contact_phone'=>$c?$c['phone_number']:'','contact_lead_status'=>$c?$c['lead_status']:'','status'=>$r['status'],'message_count'=>$r['message_count'],'unread_count'=>$r['unread_count'],'last_message_preview'=>$r['last_message_preview'],'last_message_at'=>Records::iso($r['last_message_at']),'created_at'=>Records::iso($r['created_at']),'campaign'=>self::badge($r,$labels),'last_campaign'=>self::badge($r,$labels,true),'contact'=>self::card($c));$bytes+=strlen(json_encode($item,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR));if($bytes>8388608){throw new AuthFailure(413,'Inbox page is too large. Reduce the page size.');}$items[]=$item;}
        $counts=array();$all=0;foreach($this->db->rows('SELECT v.status,COUNT(*) AS n FROM '.$this->table('conversations').' v WHERE '.$channelWhere.' GROUP BY v.status',$channelArgs) as $r){$key=$r['status']===null?'active':$r['status'];$counts[$key]=($counts[$key]??0)+(int)$r['n'];$all+=(int)$r['n'];}$counts['all']=$all;$counts['unread']=(int)$this->db->rows('SELECT COUNT(*) AS n FROM '.$this->table('conversations').' v WHERE '.$channelWhere." AND (v.status='unread' OR v.unread_count>0)",$channelArgs)[0]['n'];return array('total'=>$total,'items'=>$items,'counts'=>$counts);
    }
    public function read($id){$old=$this->conversation($id);$rows=$this->db->rows('SELECT id,direction,body,status,created_at,sent_at,delivered_at,failed_at,last_error,segment_count,provider_message_id,ai_sentiment,ai_intent,ai_confidence FROM '.$this->table('messages').' WHERE conversation_id=%d ORDER BY created_at ASC,id ASC LIMIT 1001',array($id));if(count($rows)>1000){throw new AuthFailure(413,'Thread exceeds the message admission limit.');}$messages=array();$bytes=0;foreach($rows as $row){$m=$this->db->decode('messages',$row);foreach(array('created_at','sent_at','delivered_at','failed_at') as $k){$m[$k]=Records::iso($m[$k]);}if($m['last_error']!==null&&$m['last_error']!==''){$m['last_error']='Message delivery reported an error.';}$bytes+=strlen(json_encode($m,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR));if($bytes>8388608){throw new AuthFailure(413,'Thread response is too large.');}$messages[]=$m;}$r=$this->heal($old);$p=array('unread_count'=>0);if(in_array($r['status'],array(null,'','unread'),true)){$p['status']='read';}$r=$this->change($r,$p);$contacts=$this->contacts(array($r),true);$labels=$this->labels(array($r));$out=array('id'=>$id,'campaign'=>self::badge($r,$labels),'last_campaign'=>self::badge($r,$labels,true),'contact'=>self::card($contacts[$r['contact_id']]??null,true),'status'=>$r['status'],'sequence_paused'=>$r['sequence_paused'],'messages'=>$messages);if(strlen(json_encode($out,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR))>8388608){throw new AuthFailure(413,'Thread response is too large.');}return $out;}
    public function action($id,$action,$body=null){$r=$this->conversation($id);$p=array();$lead=null;$map=array('mark-interested'=>array('interested','interested'),'mark-not-interested'=>array('not_interested','not_interested'),'mark-close'=>array('closed','closed'),'mark-opportunity'=>array('opportunity','interested'));
        if(isset($map[$action])){list($p['status'],$lead)=$map[$action];}elseif($action==='status'){if(!is_object($body)||!isset($body->status)||!is_string($body->status)){throw new ValidationFailure('A status string is required','status');}$s=strtolower(Compat::strip($body->status));if(!in_array($s,self::LABELS,true)){throw new ValidationFailure('Unsupported conversation status','status');}$p['status']=$s==='active'&&$r['unread_count']>0?'unread':$s;}elseif($action==='mark-unread'){$p=array('status'=>'unread','unread_count'=>$r['unread_count']?:1);}elseif(in_array($action,array('stop-sequence','resume-sequence'),true)){$p['sequence_paused']=$action==='stop-sequence';}else{throw new AuthFailure(404,'Conversation action not found');}
        $r=$this->change($r,$p,true);if($lead!==null){$c=$this->db->one('contacts',array('id'=>$r['contact_id']));if($c&&$c['lead_status']!==$lead){if($this->db->update('contacts',array('lead_status'=>$lead,'updated_at'=>$this->records->now()),array('id'=>$c['id'],'lead_status'=>$c['lead_status']))!==1){throw new AuthFailure(409,'Contact changed. Reload and retry.');}}}
        if($action==='stop-sequence'){$this->db->execute('UPDATE '.$this->table('followups')." SET status='cancelled',updated_at=%s WHERE contact_id=%d AND status IN ('pending','sending')",array($this->records->now(),$r['contact_id']));$this->db->execute('UPDATE '.$this->table('campaign_contacts')." SET status='replied',next_action_at=NULL,updated_at=%s WHERE contact_id=%d AND status IN ('pending','queued','sent')",array($this->records->now(),$r['contact_id']));}
        return array('success'=>true,in_array($action,array('stop-sequence','resume-sequence'),true)?'sequence_paused':'status'=>in_array($action,array('stop-sequence','resume-sequence'),true)?$r['sequence_paused']:$r['status']);
    }
    public function preview($id,$templateId){$r=$this->conversation($id);$t=$this->db->one('templates',array('id'=>$templateId,'is_active'=>1));if(!$t){throw new AuthFailure(404,'Template not found or inactive');}$c=$this->db->one('contacts',array('id'=>$r['contact_id']));list($a,$f)=(new Variables($this->db))->maps();$body=Templating::render($t['body'],$c,$a,$f);list($chars,$segments)=Templating::segments($body);return array('template_id'=>$t['id'],'template_name'=>$t['name'],'body'=>$body,'char_count'=>$chars,'segment_count'=>$segments);}
    public function campaignFilters(array $q){$channel=$this->channel($q);$where=$channel==='all'?'1=1':"COALESCE(v.channel,'sms')=%s";$args=$channel==='all'?array():array($channel);$last=0;$buckets=array();$unattributed=array('leads'=>0,'replies'=>0,'unread'=>0);$total=0;
        do{$rows=$this->db->rows('SELECT v.*,EXISTS (SELECT 1 FROM '.$this->table('messages')." m WHERE m.conversation_id=v.id AND m.direction='incoming') AS __ss_replied FROM ".$this->table('conversations').' v WHERE '.$where.' AND v.id>%d ORDER BY v.id ASC LIMIT 200',array_merge($args,array($last)));foreach($rows as $raw){$replied=(bool)$raw['__ss_replied'];$r=$this->db->decode('conversations',$raw);$last=$r['id'];$total++;$key=$r['campaign_id']?'campaign:'.$r['campaign_id']:($r['ads_campaign_id']?'ads:'.$r['ads_campaign_id']:null);if($key===null){$target=&$unattributed;}else{if(!isset($buckets[$key])){$buckets[$key]=array('row'=>$r,'leads'=>0,'replies'=>0,'unread'=>0);}$target=&$buckets[$key];}$target['leads']++;if($replied){$target['replies']++;}if($r['unread_count']||$r['status']==='unread'){$target['unread']++;}unset($target);}if(count($buckets)>10000){throw new AuthFailure(413,'Too many inbox campaign buckets.');}}while(count($rows)===200);
        $labels=$this->labels(array_column($buckets,'row'));$items=array();foreach($buckets as $key=>$b){if(isset($labels[$key])){unset($b['row']);$items[]=array_merge($labels[$key],$b);}}usort($items,function($a,$b){return $b['leads']<=>$a['leads']?:strcmp($a['name'],$b['name']);});return array('items'=>$items,'unattributed'=>$unattributed,'total_conversations'=>$total);
    }
    public static function handle($request,array $context){$path=trim(substr($request->get_route(),strlen('/sender-suite/v1/')),'/');$method=$request->get_method();$s=new self($context['db']);$q=$request->get_query_params();if($method==='GET'){if($path==='inbox/conversations'){return $s->listing($q);}if($path==='inbox/campaign-filters'){return $s->campaignFilters($q);}}
        if(preg_match('~^inbox/conversations/(-?[0-9]+)(?:/templates/(-?[0-9]+)/preview|/(mark-interested|mark-not-interested|mark-close|mark-opportunity|status|mark-unread|stop-sequence|resume-sequence))?$~D',$path,$m)){$id=DataRoutes::integer($m[1],'conversation_id');if($method==='GET'){if(isset($m[2])&&$m[2]!==''){return $s->preview($id,DataRoutes::integer($m[2],'template_id'));}if(!isset($m[3])||$m[3]===''){return $s->read($id);}}elseif($method==='POST'&&isset($m[3])&&$m[3]!==''){$body=null;if($m[3]==='status'){if(strlen($request->get_body())>4096){throw new AuthFailure(413,'Status request is too large.');}$body=DataRoutes::body($request);}return $s->action($id,$m[3],$body);}}throw new AuthFailure(404,'Application endpoint not found.');
    }
}
